from m_lib import *


def add():
    h1('7. Part F – Evaluation on the test plots')
    p('Every model of Part E predicts the %d test leaves once. Nothing is changed after this step.' % CNT['test'])
    card('F1', 'Detection metrics (Task A)',
         what='Confusion matrix → overall accuracy (OA), Cohen\'s kappa, macro-F1, sensitivity (recall of diseased leaves), specificity (recall of healthy leaves), precision; area under the ROC curve (AUC) from the predicted probability or decision value.',
         why='OA alone hides which error a model makes; macro-F1 treats the healthy and diseased classes equally although healthy leaves are fewer; AUC does not depend on one decision threshold.',
         papers=L('Ma et al. (2026): OA, Cohen\'s kappa, macro-average recall, macro-average F1, per-class precision/recall/F1 and specificity on the test set.',
                  'Selvaprakash et al. (2026): F1, kappa and AUC of rice blast indices.',
                  'Lv et al. (2023): OA, macro-F1 and kappa for asymptomatic and symptomatic detection.',
                  'Mahlein et al. (2013): sensitivity and specificity of the sugar-beet disease indices.'),
         match='The metric set of Ma et al. (2026) plus AUC as in Selvaprakash et al. (2026).',
         mine='Main metric macro-F1; formulas after Cohen (1960), Fawcett (2006), Sokolova and Lapalme (2009); AUC after Hanley and McNeil (1982).',
         out='Detection table and ROC curves.')
    card('F2', 'Ordinal metrics for six grades (Task B)',
         what='OA, kappa, macro-F1 and the F1 of each grade; quadratic weighted kappa (QWK); share of leaves predicted within one class; confusion matrix.',
         why='The grades are ordered: confusing grade 3 with 5 is a smaller error than 0 with 9. QWK and the within-one-class share give partial credit; per-grade F1 shows which grades fail.',
         papers=L('Ma et al. (2026): per-class precision, recall and F1 and macro-F1 for five rice blast severity levels.',
                  'Zhang et al. (2012): overall accuracy, kappa, producer\'s and user\'s accuracy for normal, slight and heavy powdery mildew.',
                  'Chen et al. (2023): six-class severity models (grades 0, 1, 3, 5, 7, 9) evaluated class by class.'),
         match='Per-class metrics as in Ma et al. (2026) and Zhang et al. (2012). QWK (Cohen, 1968) is added because the grades are ordinal; weighted kappa is the recommended accuracy measure for ordinal classifiers (Ben-David, 2008). Within-one-class accuracy is added because visual raters disagree most between neighbouring classes (Bock et al., 2010).',
         mine='Main metric macro-F1; QWK with quadratic weights over the six classes; interpretation of kappa values after Landis and Koch (1977).',
         out='Six-grade table, per-grade F1, confusion matrices.')
    card('F3', 'Regression metrics (Task C)',
         what='R², RMSE, MAE, RPD (SD of observed / RMSE), bias (mean predicted − observed), correlation r; predicted-against-observed plot with the 1:1 line and the mean ± SD of predictions per grade.',
         why='R² gives explained variation, RMSE the error in grade units, RPD a scale-free quality class and bias the systematic error.',
         papers=L('Mandal et al. (2023): R², RMSE and RPD of rice blast severity models (for example RPD 1.53 for a PLS model).',
                  'Wang et al. (2016): R² and RMSE of PLS and SVR models of wheat stripe and leaf rust severity.',
                  'Krishna et al. (2014): RPD of PLSR models of wheat yellow rust from hyperspectral data.'),
         match='The R², RMSE and RPD of Mandal et al. (2023) and Wang et al. (2016).',
         mine='RPD classes: > 2.0 good, 1.4–2.0 fair, < 1.4 poor (Chang et al., 2001; RPD itself after Williams, 2001); its limitations after Bellon-Maurel et al. (2010).',
         out='Regression table and predicted-observed plots.')
    card('F4', 'Uncertainty: bootstrap of whole test plots',
         what='The 4 healthy and 11 unsprayed test plots are drawn with replacement (separately), all leaves of the drawn plots are taken and the metric is recomputed; 1000 resamples give the standard error and the 95% interval.',
         why='With one test set there are no folds; resampling single leaves would ignore that leaves of a plot are related.',
         papers=L('No disease study reports a plot bootstrap; the method follows Field and Welsh (2007) for clustered data and Efron and Tibshirani (1993).',
                  'Ma et al. (2026) and Mandal et al. (2023) reported single test-set values without intervals; the bootstrap adds the uncertainty they did not give.'),
         match='Cluster (plot) bootstrap; strata = healthy and unsprayed plots, as in the split.',
         mine='1000 resamples, seed 42; percentile intervals.',
         out='± standard errors and 95% intervals of every metric.')
    card('F5', 'Interpretation with SHAP',
         what='SHAP values of an XGBoost model on the Objective 1 DSF: direction and size of each feature\'s effect on the predicted grade.',
         why='Links the models to physiology (chlorophyll, structure, water) and shows that they use the disease signal.',
         papers=L('Ma et al. (2026): SHAP plots showed how high and low values of the selected bands pushed the rice blast prediction.',
                  'Lundberg and Lee (2017); Lundberg et al. (2020): SHAP and TreeSHAP.'),
         match='SHAP summary plots as in Ma et al. (2026).',
         mine='TreeSHAP of XGBoost (300 trees, depth 4, learning rate 0.05).',
         out='SHAP summary and importance by grade → discussion.')
    card('F6', 'Robustness: strata and transfer to an unseen group',
         what='(1) Test metrics within growth stage, variety, leaf position, sampling date and sowing date. (2) Leave-one-variety-out and leave-one-sowing-date-out: train on all other groups (selection repeated inside), test on the held-out group. (3) Leave-one-date-out as an additional transfer check.',
         why='A model useful in the field must not depend on one variety, sowing date or sampling date.',
         papers=L('Ma et al. (2026): cross-year independent validation (trained on 2023, tested on 2024).',
                  'In my replications of Zhang et al. (2012), Tian et al. (2021) and Lv et al. (2023) on these leaves, leave-one-date-out validation was added and accuracy fell on unseen dates – so transfer checks are part of the methodology.'),
         match='Held-out groups play the role of the independent year of Ma et al. (2026); grouping follows Roberts et al. (2017).',
         mine='Random forest (500 trees) with selection repeated inside each training part; macro-F1 (B) and RMSE (C).',
         out='Transfer tables → discussion of generalisation.')
    card('F7', 'Stability of the selected features',
         what='How often each optimal wavelength, index and wavelet feature is chosen across training sets (TRAIN and the three leave-one-replication-out training parts).',
         why='Features chosen in most training sets are more trustworthy for sensor design than features chosen once.',
         papers=L('Ma et al. (2026): repeated CARS iterations to improve selection stability.',
                  'Nogueira et al. (2018) and Kalousis et al. (2007): measures of feature-selection stability.'),
         match='Selection-frequency count across training sets.',
         mine='Four training sets; frequency of each feature.',
         out='Stability plot → discussion.')

    h1('8. Part G – Covariate baseline, and Part H – check of the validation design')
    card('G1', 'Covariate-only models (sensor-free baseline)',
         what='Models built from covariates only – crop age (DAS, DAS²), sowing date, variety, growth stage, 7-day weather and favourable days: B1 interpretable (logistic regression for A, proportional-odds ordinal logistic regression for B, linear regression for C), random forest, and the best machine-learning model of Part E.',
         why='Severity rises with crop age and date; a spectral model could look accurate by learning the calendar. The spectra are credited only with what they add to these models.',
         papers=L('Bhattacharya and Chattopadhyay (2013): mustard rot disease tracked by combining surface meteorology with satellite remote sensing.',
                  'Zhang et al. (2014a): adding remote sensing to meteorological data improved forecasts of wheat powdery mildew.',
                  'Ruan et al. (2022): remote sensing and meteorological data combined to predict wheat stripe rust.',
                  'Chattopadhyay et al. (2011): weather-based forecasting of white rust of Indian mustard.'),
         match='Weather-only against weather + sensor models, as in Zhang et al. (2014a) and Bhattacharya and Chattopadhyay (2013), at leaf level.',
         mine='Unsprayed leaves only (TRAIN %d, TEST %d); the sprayed plots share every covariate with unsprayed plots but are healthy because of the fungicide, so they are excluded. Ordinal model after McCullagh (1980); DAS² after Madden et al. (2007).' % (CNT['utr'], CNT['ute']),
         out='M0 = the stronger covariate-only model → G2.')
    card('G2', 'Spectra and spectra + covariates',
         what='M1 = the best machine-learning model on the DSF; M2 = the same model on DSF + covariates; same split, same inner tuning by plot.',
         why='Three model sets answer: how much do the covariates explain (M0), what do the spectra achieve (M1), and does known context add to the spectra (M2)?',
         papers=L('Zhang et al. (2014a) and Ruan et al. (2022): models with meteorological data, with sensor data and with both.'),
         match='The three-way comparison of these studies.',
         mine='Unsprayed leaves; best ML model of each task (Step E).',
         out='M0, M1, M2 predictions → G3.')
    card('G3', 'Gains and their uncertainty',
         what='ΔS = M1 − M0 (gain of the spectra), ΔC = M2 − M1 (gain of the covariates added to the spectra), ΔT = M2 − M0; 95% interval from 2000 paired bootstrap resamples of the 11 unsprayed test plots; DeLong test for the detection AUCs.',
         why='A gain counts only if it is larger than the uncertainty of the test set.',
         papers=L('DeLong et al. (1988): test for two correlated AUCs; Sun and Xu (2014): its fast implementation.',
                  'Field and Welsh (2007): bootstrap of clustered data.'),
         match='Paired plot bootstrap and DeLong test.',
         mine='A gain is real when its 95% interval excludes zero.',
         out='Gain table → conclusion on the value of the spectra.')
    card('H1', 'Repeated grouped 70:30 splits',
         what='20 other rule-conforming grouped 70:30 splits (same rules as B1) are run with a light pipeline (selection on the training part; SVM for A, random forest for B, XGBoost for C; grid search; no SFFS).',
         why='One split gives one test set; the spread over other possible splits shows how much the test accuracy depends on which plots were drawn.',
         papers=L('Ma et al. (2026) and Mandal et al. (2023) reported a single split; Wang et al. (2016) added external validation.',
                  'Kohavi (1995) and Vabalas et al. (2019): the variance of hold-out estimates with small samples.'),
         match='Adds the split-to-split variability that single-split disease studies do not report.',
         mine='Candidates with score ≤ the median score; seed 7.',
         out='Range of hold-out accuracy → interpretation of the main split.')
    card('H2', 'Leakage check: random leaf-level 70:30 splits',
         what='Five random 70:30 splits of leaves (stratified by grade, plots ignored), with the same light pipeline.',
         why='Shows how much accuracy would be inflated if leaves of the same plot were in training and test, as in random leaf splits.',
         papers=L('Kattenborn et al. (2022): random splits over-estimated accuracy compared with spatially blocked splits.',
                  'Roberts et al. (2017): blocked validation for dependent samples.'),
         match='The random-versus-blocked comparison of Kattenborn et al. (2022) on leaf data.',
         mine='random_state 100–104.',
         out='Size of the leakage → justification of B1.')
    card('H3', 'Paired comparison with leave-one-replication-out (LORO)',
         what='The LORO predictions of exactly the test leaves are compared with the 70:30 predictions; difference with a 95% plot-bootstrap interval.',
         why='LORO tests every leaf once by holding out whole replications; comparing on the same leaves separates the effect of the design from the effect of the test set.',
         papers=L('Dietterich (1998): comparing classifiers on the same test data.',
                  'Roberts et al. (2017): replication or block hold-out for hierarchical data.'),
         match='Paired comparison on identical test leaves.',
         mine='2000 bootstrap resamples of the test plots (healthy and unsprayed separately).',
         out='Answer to "does the design change the accuracy?".')
    card('I1', 'Software, seeds and delivered models',
         what='Python 3 (NumPy, pandas, SciPy, scikit-learn, mlxtend, XGBoost, SHAP, PyWavelets, PyTorch). Fixed seeds: split 2026, models 42. The delivered models are the tested models, trained on the training plots only; they are saved with their scaler, feature list and a prediction script for new spectra.',
         why='Reproducibility and an honest link between reported accuracy and delivered files.',
         papers=L('Ma et al. (2026): fixed seed 42 and deterministic computation; Python 3.12.'),
         match='Same fixed-seed practice.',
         mine='Scripts in run order (Appendix B); every setting listed in Appendix B.',
         out='Model files, workbook, report.')
